  Lemma path_facts :
    rdn RSEGS mem0 (p1 a0s path envv rdraw) (length path + 1) = Some (path ++ [Z_to_bv 8 0])
    /\ (bv_unsigned sp0 <= bv_unsigned (p1 a0s path envv rdraw))%Z
    /\ (bv_unsigned (p1 a0s path envv rdraw) <= bv_unsigned sp0 + 2107576)%Z
    /\ exists t8, rdn RSEGS mem0 (Z_to_bv 64 (bv_unsigned (p1 a0s path envv rdraw) + Z.of_nat (length path))) 8 = Some t8.
Proof.
  (* LPS 727298f3: argv[1] in the revised entry block; [S1MainEntryN.main_strN] at k = 1 *)
  destruct (S1MainEntryN.main_strN sp0 [a0s; path] envv tid rdraw regs0 mem0 Hva Hve Hvsp ME 1 ltac:(cbn; lia))
    as (R1 & R2 & R3 & _ & R5).
  cbn [nth] in R1, R5.
  split; [exact R1|]. split; [exact R2|]. split; [exact R3 | exact R5].
Qed.

  (* LPS 727298f3: argv[1]'s string ends below the stack window's top, from the launch facts
     ([S1Start.argv_str_fits] at this Section's input); [ref_open_fail_errno]'s recorded proof uses it for [of_tail]. *)
  Lemma p1_path_fits :
    (bv_unsigned (cat_argv_ptr (ed_top rdraw) [a0s; path] envv a_execfn 1) + Z.of_nat (length (nth 1 [a0s; path] [])) + 1
       <= sp_window_hi)%Z.
  Proof.
    destruct (me_lau _ _ _ _ _ _ _ ME) as [brk0 Hlau].
    exact (argv_str_fits sp0 mbase brk0 rdraw INP 1 Hvsp Hva Hve (me_vl _ _ _ _ _ _ _ ME) Hlau ltac:(cbn; lia)).
  Qed.

  Theorem ref_open_fail_errno : forall e vals R M,
    (1 <= e <= 4095)%Z ->
    length vals = 39%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 38 = errno_ret e ->
    vals_ev vals 2 = p1 a0s path envv rdraw ->
    regs_ok (ENV vals) (sr_upd srA (ridx 10) (EVar 38)) R -> know_ok RSEGS (ENV vals) M knA ->
    (forall x : word, (bv_unsigned sp0 <= bv_unsigned x)%Z -> M x = mem0 x) ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xe1e50) M (seg_rom RSEGS)) model0)
               (t_die (msg_cannot_open path) fs0).
Proof.
